#include "nxt_led.h"
#include "nxt_skin.h"
#include "background.h"
#include <stdio.h>
#include <math.h>
static const unsigned palette[16]={0x9de4b6,0x82b7ed,0xedbf7a,0xe7a0bf,0xffffff,0xff4040,0xff8000,0xffeb00,0x80ff00,0x00e060,0x00ffff,0x0080ff,0x3030ff,0x8000ff,0xff00ff,0xff0080};
static const char *en[]={"Mint","Blue","Amber","Pink","White","Red","Orange","Yellow","Lime","Green","Cyan","Azure","Indigo","Violet","Magenta","Rose","Custom RGB"};
static const char *vi[]={"Mint","Xanh dương","Vàng cam","Hồng","Trắng","Đỏ","Cam","Vàng","Xanh chanh","Xanh lá","Xanh ngọc","Xanh trời","Chàm","Tím","Hồng tím","Hồng đậm","RGB tự chọn"};
unsigned NxtLED_rgb(void){return nxt.led_color>=0&&nxt.led_color<16?palette[nxt.led_color]:(unsigned)nxt.led_rgb&0xffffff;}
const char *NxtLED_name(int i){return Nxt_text(en[i],vi[i]);}
const char *NxtLED_effectName(int i){static const char *en[]={"Solid","Two-color gradient","Rainbow wave","Split colors","Aurora","Breathing"},*vi[]={"Một màu","Gradient hai màu","Sóng cầu vồng","Chia hai màu","Cực quang","Nhịp thở"};return Nxt_text(en[i>=0&&i<6?i:0],vi[i>=0&&i<6?i:0]);}
static unsigned blend(unsigned a,unsigned b,float t){if(t<0)t=0;if(t>1)t=1;unsigned out=0;for(int shift=0;shift<=16;shift+=8){int x=(a>>shift)&255,y=(b>>shift)&255;out|=(unsigned)(x+(y-x)*t)<<shift;}return out;}
unsigned NxtLED_groupRGB(int i,uint32_t now){unsigned first=NxtLED_rgb(),second=nxt.led_rgb2;float pos=i==0?.5f:i==1?0:i==2?.33f:i==3?.66f:1.f;switch(nxt.led_effect){case 1:return blend(first,second,pos);case 2:{float hue=fmodf(now/8000.f+pos*.5f,1.f)*6;int sector=(int)hue;float fraction=hue-sector;unsigned r=0,g=0,b=0,v=255,x=255*(1-fraction),y=255*fraction;switch(sector){case 0:r=v;g=y;break;case 1:r=x;g=v;break;case 2:g=v;b=y;break;case 3:g=x;b=v;break;case 4:r=y;b=v;break;default:r=v;b=x;break;}return(r<<16)|(g<<8)|b;}case 3:return i==2||i==4?second:first;case 4:return blend(first,second,.5f+.5f*sinf(now/1600.f+pos*4));case 5:return blend(0,first,.15f+.85f*(.5f+.5f*sinf(now/1800.f)));default:return first;}}
static SDL_Color color(unsigned rgb){return(SDL_Color){rgb>>16,(rgb>>8)&255,rgb&255,255};}
ModuleExitReason NxtLED_palette(DisplayContext *d){int old_effect=nxt.led_effect,enabled=nxt.led,mode=nxt.led_mode,strength=nxt.led_strength,old_color=nxt.led_color,old_rgb=nxt.led_rgb,component=0,show=0;bool save=false;ModuleExitReason result=MODULE_EXIT_TO_MENU;unsigned rgb=NxtLED_rgb();nxt.led=1;nxt.led_mode=0;nxt.led_effect=0;if(nxt.led_strength<30)nxt.led_strength=30;for(;;){ModuleCommon_frameBegin();Background_tick();SDL_Surface *s=DisplayHelper_getSurface(d);GlobalInputResult g=ModuleCommon_handleGlobalInput(s,&show,HELP_NONE);if(g.should_quit){result=MODULE_EXIT_QUIT;break;}if(!g.input_consumed&&!Nxt_lockInput()){if(NxtPad_justPressed(BTN_B))break;if(NxtPad_justPressed(BTN_A)){save=true;break;}if(NxtPad_justRepeated(BTN_UP))component=(component+2)%3;if(NxtPad_justRepeated(BTN_DOWN))component=(component+1)%3;int delta=NxtPad_justRepeated(BTN_RIGHT)-NxtPad_justRepeated(BTN_LEFT)+16*(NxtPad_justRepeated(BTN_R1)-NxtPad_justRepeated(BTN_L1));if(delta){int shift=(2-component)*8,v=((rgb>>shift)&255)+delta;if(v<0)v=0;if(v>255)v=255;rgb=(rgb&~(255u<<shift))|((unsigned)v<<shift);nxt.led_color=16;nxt.led_rgb=rgb;}int preset=NxtPad_justPressed(BTN_X)-NxtPad_justPressed(BTN_Y);if(preset){nxt.led_color=(nxt.led_color+preset+16)%16;rgb=palette[nxt.led_color];nxt.led_rgb=rgb;}}NxtSkin_begin(s,Nxt_text("LED color palette","Bảng màu LED"),NULL,false);int u=s->w;char hex[80];snprintf(hex,sizeof(hex),"#%06X · %s",rgb,NxtLED_name(nxt.led_color));NxtSkin_rect(s,(SDL_Rect){40*u/1024,140*u/1024,160*u/1024,136*u/1024},color(rgb),14*u/1024);NxtSkin_text(s,28,hex,228*u/1024,164*u/1024,750*u/1024,NxtSkin_color(NXT_INK));for(int i=0;i<16;i++)NxtSkin_rect(s,(SDL_Rect){(228+(i%8)*88)*u/1024,(226+(i/8)*54)*u/1024,72*u/1024,38*u/1024},color(palette[i]),7*u/1024);for(int i=0;i<3;i++){int y=(358+i*70)*u/1024,v=(rgb>>((2-i)*8))&255;char text[24];snprintf(text,sizeof(text),"%c %3d","RGB"[i],v);NxtSkin_text(s,25,text,48*u/1024,y,150*u/1024,NxtSkin_color(i==component?NXT_ACCENT:NXT_INK));NxtSkin_rect(s,(SDL_Rect){215*u/1024,y+8*u/1024,730*u/1024,24*u/1024},NxtSkin_color(NXT_PANEL),8*u/1024);NxtSkin_rect(s,(SDL_Rect){215*u/1024,y+8*u/1024,730*u/1024*v/255,24*u/1024},color(0xffu<<((2-i)*8)),8*u/1024);}NxtSkin_text(s,20,Nxt_text("↑↓ RGB · ←→ ±1 · L1/R1 ±16 · X/Y Preset","↑↓ R/G/B · ←→ ±1 · L1/R1 ±16 · X/Y Màu"),48*u/1024,598*u/1024,928*u/1024,NxtSkin_color(NXT_MUTED));NxtSkin_footer(s,Nxt_text("A Save • B Cancel","A Lưu • B Hủy"),false);ModuleCommon_markSurfaceDrawn();int dirty=1;ModuleCommon_PWR_update(&dirty,&show);ModuleCommon_frameEnd(s);}nxt.led=save?1:enabled;nxt.led_mode=mode;nxt.led_effect=old_effect;nxt.led_strength=strength;if(!save){nxt.led_color=old_color;nxt.led_rgb=old_rgb;}else Nxt_save();return result;}
